import {
  S3Client,
  GetObjectCommand,
  HeadObjectCommand,
  PutObjectCommand,
  DeleteObjectCommand,
  DeleteObjectsCommand,
  ListObjectsV2Command,
} from "@aws-sdk/client-s3";
import { notFound, preconditionFailed, invalidCursor } from "./problems.mjs";

// S3 access for one Space, whose bucket is named for the space id. Keys are
// rooted at the Space:
//
//   meta/space.json              Space Metadata
//   meta/{c}.json                Collection Metadata (configuration + custom)
//   meta/{c}/{r}.json            Resource Metadata (the user-writable part)
//   policies/space.json          access-control policies, keyed by scope
//   policies/{c}.json
//   policies/{c}/{r}.json
//   collections/{c}/{r}          Resource content
//
// Metadata and policies never appear in listings because they live outside
// collections/. Conditional writes (If-Match / If-None-Match: *) go through
// S3's own conditional PutObject and DeleteObject, so a precondition is
// evaluated atomically with the write.

const s3 = new S3Client({});

export const KEYS = {
  spaceMeta: () => "meta/space.json",
  collectionMeta: (c) => `meta/${c}.json`,
  resourceMeta: (c, r) => `meta/${c}/${r}.json`,
  spacePolicy: () => "policies/space.json",
  collectionPolicy: (c) => `policies/${c}.json`,
  resourcePolicy: (c, r) => `policies/${c}/${r}.json`,
  resource: (c, r) => `collections/${c}/${r}`,
  collectionPrefix: (c) => `collections/${c}/`,
  collectionMetaPrefix: (c) => `meta/${c}/`,
  collectionPolicyPrefix: (c) => `policies/${c}/`,
};

const isMissing = (err) =>
  err?.name === "NoSuchKey" ||
  err?.name === "NotFound" ||
  err?.$metadata?.httpStatusCode === 404;

const isNoBucket = (err) => err?.name === "NoSuchBucket";

const isPrecondition = (err) =>
  err?.name === "PreconditionFailed" ||
  err?.name === "ConditionalRequestConflict" ||
  err?.$metadata?.httpStatusCode === 412 ||
  err?.$metadata?.httpStatusCode === 409;

const isNotModified = (err) => err?.name === "NotModified" || err?.$metadata?.httpStatusCode === 304;

// Wraps an S3 call: a missing bucket is the Space not existing (404), a
// failed precondition is the spec's 412.
async function call(command) {
  try {
    return await s3.send(command);
  } catch (err) {
    if (isNoBucket(err)) {
      throw notFound();
    }
    if (isPrecondition(err)) {
      throw preconditionFailed("The If-Match or If-None-Match precondition was not met.");
    }
    throw err;
  }
}

// An object with its body as a Buffer, or null when the key does not exist.
// `ifNoneMatch` returns { notModified: true } on a 304.
export async function getObject(bucket, key, { ifNoneMatch } = {}) {
  try {
    const out = await call(
      new GetObjectCommand({
        Bucket: bucket,
        Key: key,
        ...(ifNoneMatch !== undefined && { IfNoneMatch: ifNoneMatch }),
      })
    );
    return {
      body: Buffer.from(await out.Body.transformToByteArray()),
      contentType: out.ContentType,
      contentLength: out.ContentLength,
      etag: out.ETag,
      lastModified: out.LastModified,
      metadata: out.Metadata ?? {},
    };
  } catch (err) {
    if (isMissing(err)) {
      return null;
    }
    if (isNotModified(err)) {
      return { notModified: true };
    }
    throw err;
  }
}

export async function getJson(bucket, key) {
  const object = await getObject(bucket, key);
  if (object === null) {
    return null;
  }
  try {
    return { doc: JSON.parse(object.body.toString("utf8")), etag: object.etag };
  } catch {
    return { doc: {}, etag: object.etag };
  }
}

export async function headObject(bucket, key) {
  try {
    const out = await call(new HeadObjectCommand({ Bucket: bucket, Key: key }));
    return {
      contentType: out.ContentType,
      contentLength: out.ContentLength,
      etag: out.ETag,
      lastModified: out.LastModified,
      metadata: out.Metadata ?? {},
    };
  } catch (err) {
    if (isMissing(err)) {
      return null;
    }
    throw err;
  }
}

// Writes an object, honoring If-Match (update-if-unchanged) and
// If-None-Match: * (create-if-absent). Resolves to the new ETag.
export async function putObject(bucket, key, { body, contentType, metadata, ifMatch, ifNoneMatch }) {
  const out = await call(
    new PutObjectCommand({
      Bucket: bucket,
      Key: key,
      Body: body,
      ContentType: contentType,
      ...(metadata && { Metadata: metadata }),
      ...(ifMatch !== undefined && { IfMatch: ifMatch }),
      ...(ifNoneMatch !== undefined && { IfNoneMatch: ifNoneMatch }),
    })
  );
  return { etag: out.ETag };
}

export async function putJson(bucket, key, doc, options = {}) {
  return putObject(bucket, key, {
    ...options,
    body: JSON.stringify(doc),
    contentType: "application/json",
  });
}

// Deletes one object; `ifMatch` makes the delete conditional on the current
// ETag. Deleting a missing key is not an error here (callers that need a 404
// check existence first).
export async function deleteObject(bucket, key, { ifMatch } = {}) {
  await call(
    new DeleteObjectCommand({
      Bucket: bucket,
      Key: key,
      ...(ifMatch !== undefined && { IfMatch: ifMatch }),
    })
  );
}

// One page of keys under a prefix. With a delimiter, the sub-prefixes come
// back as `prefixes`. `cursor` is S3's continuation token, opaque to clients.
export async function listObjects(bucket, { prefix, delimiter, cursor, limit }) {
  let out;
  try {
    out = await call(
      new ListObjectsV2Command({
        Bucket: bucket,
        Prefix: prefix,
        ...(delimiter && { Delimiter: delimiter }),
        ...(cursor !== undefined && { ContinuationToken: cursor }),
        ...(limit !== undefined && { MaxKeys: limit }),
      })
    );
  } catch (err) {
    if (err?.name === "InvalidArgument" || err?.$metadata?.httpStatusCode === 400) {
      throw invalidCursor("The cursor was not issued by this listing.");
    }
    throw err;
  }
  return {
    objects: (out.Contents ?? []).map((entry) => ({
      key: entry.Key,
      size: entry.Size,
      etag: entry.ETag,
      lastModified: entry.LastModified,
    })),
    prefixes: (out.CommonPrefixes ?? []).map(({ Prefix }) => Prefix),
    next: out.IsTruncated ? out.NextContinuationToken : undefined,
  };
}

// Every key under a prefix, across pages.
export async function listAllKeys(bucket, prefix) {
  const keys = [];
  let cursor;
  do {
    const page = await listObjects(bucket, { prefix, cursor });
    keys.push(...page.objects.map(({ key }) => key));
    cursor = page.next;
  } while (cursor);
  return keys;
}

// Every immediate sub-prefix under a prefix (the "folders"), across pages.
export async function listAllPrefixes(bucket, prefix) {
  const prefixes = [];
  let cursor;
  do {
    const page = await listObjects(bucket, { prefix, delimiter: "/", cursor });
    prefixes.push(...page.prefixes);
    cursor = page.next;
  } while (cursor);
  return prefixes;
}

export async function deleteKeys(bucket, keys) {
  for (let index = 0; index < keys.length; index += 1000) {
    const batch = keys.slice(index, index + 1000);
    await call(
      new DeleteObjectsCommand({
        Bucket: bucket,
        Delete: { Objects: batch.map((Key) => ({ Key })), Quiet: true },
      })
    );
  }
}

export async function deletePrefix(bucket, prefix) {
  const keys = await listAllKeys(bucket, prefix);
  if (keys.length) {
    await deleteKeys(bucket, keys);
  }
}

export { s3, isNoBucket };
